INSERT INTO `announcement_comments` (`id`, `announcement_id`, `user_id`, `body`, `created_at`, `updated_at`) VALUES (1,2,9,'Is the quiz open book, and does the attempt count if I run out of time?','2026-08-20 21:22:17','2026-08-20 21:22:17');
INSERT INTO `announcement_comments` (`id`, `announcement_id`, `user_id`, `body`, `created_at`, `updated_at`) VALUES (2,2,4,'Open book, yes. The timer is a guide for now, so a slow attempt still submits and still counts.','2026-08-20 21:22:17','2026-08-20 21:22:17');
